"""Materialize the final pre-evaluation scientific freeze, no outcome access."""
import json,hashlib
import forecast as f
res=json.loads((f.TASK/'DEVELOPMENT_RESULT.json').read_text())
rev=json.loads((f.TASK/'DEVELOPMENT_REVISION.json').read_text())
checks=json.loads((f.TASK/'ADVERSARIAL_DEVELOPMENT.json').read_text())
assert (f.TASK/'PREFIX_READER_CONTROL.json').exists()
assert not (f.TASK/'EVALUATION_PREFIX_ACCESS.json').exists()
cfg=dict(classes=res['classes'],scales=res['scales'],bins=res['bins'],primary=res['modalities'],neural_simple=dict(model=res['modalities']['neural']['strongest_simple'],alpha=res['modalities']['neural']['configs'][res['modalities']['neural']['strongest_simple']]['alpha']),behavior_simple_components=[x['best'] for x in rev['components']],fractional=checks['fractional_fluorescence_sensitivity'],bootstrap_seed=20261031,bootstrap_replicates=20000)
names=['forecast.py','prepare.py','prefix_reader.py','evaluation.py','freeze.py','SPLIT.json','PROTOCOL.md','ANALYSIS_PLAN.md','DEVELOPMENT_RESULT.json','DEVELOPMENT_REVISION.json','ADVERSARIAL_DEVELOPMENT.json','PREFIX_READER_CONTROL.json','KNOWN_ANSWER_CONTROLS.json']
pins={n:hashlib.sha256((f.TASK/n).read_bytes()).hexdigest() for n in names}
out=dict(at_utc=f.now(),configuration=cfg,code_and_config_sha256=pins,evaluation_animals=7,evaluation_outcomes_decoded=0,development_revisions=1,reason_for_once_only_evaluation='Original compact-state development gains are small (neural2.2%,behavior-0.4%). The strongest contrary test found a substantial simple individual reversal forecast (45% CV gain versus shared mean), with zero-pumping an effective distinct baseline. A held-animal comparison can distinguish this limited positive from development selection and test the claimed need for extra global state. Main neural+behavior rule unchanged; no equivalence inference from a failure. Synthetic controls show strong-signal gain in94/100 but investment-rule sensitivity57/100, so this small study may remain uncertain.',permissions='Transfer/hash all7 pinned raw heat files; lexically traverse but numerically decode only whitelisted timing/labels and responses earlier than-5s. Save immutable forecasts first. Only a later separate scoring command may numerically decode full evaluation outcomes. Raw bytes and cache rereads charged. No old protected cohorts released.',summary_exposure='All19 publication/mirror aggregate summaries; specific2023-01-05-01 named in Morrison/Young. Prespecified sensitivity excludes that UID; no raw evaluation outcomes yet.',decision_rule='>=10% state MSE reduction over strongest simple forecast in both modalities, with positive paired animal-bootstrap95%lower improvement in both; no model/endpoint changes on evaluation')
f.save('EVALUATION_FREEZE.json',out)
print(json.dumps(dict(at_utc=out['at_utc'],evaluation_animals=7,neural_simple=cfg['neural_simple'],behavior_simple=[{k:v for k,v in x.items() if k in ['model','alpha','mse']} for x in cfg['behavior_simple_components']],code_and_config_sha256=pins),indent=2))
